CREATE TABLE public.xpert_project_pipeline_attention ( id uuid DEFAULT gen_random_uuid() NOT NULL, "createdById" uuid, "updatedById" uuid, "createdAt" timestamp with time zone DEFAULT now() NOT NULL, "updatedAt" timestamp with time zone DEFAULT now() NOT NULL, "tenantId" uuid, "organizationId" uuid, "projectId" uuid, "deletedAt" timestamp without time zone, "instanceId" uuid NOT NULL, "nodeInstanceId" uuid NOT NULL, "roundId" uuid NOT NULL, kind character varying NOT NULL, state character varying NOT NULL, revision integer DEFAULT 1 NOT NULL, "reasonCode" character varying NOT NULL, "inputDigest" character varying NOT NULL, generation integer NOT NULL, "policyRef" character varying, "candidateRoleKey" character varying, outcomes jsonb DEFAULT '[]'::jsonb NOT NULL, "decisionId" uuid, CONSTRAINT pipeline_attention_values_check CHECK (((revision > 0) AND (generation > 0) AND ((kind)::text = ANY ((ARRAY['human'::character varying, 'blocked'::character varying, 'unknown'::character varying])::text[])) AND ((state)::text = ANY ((ARRAY['open'::character varying, 'resolved'::character varying, 'superseded'::character varying])::text[])))) );
CREATE TABLE public.xpert_project_pipeline_binding ( id uuid DEFAULT gen_random_uuid() NOT NULL, "createdById" uuid, "updatedById" uuid, "createdAt" timestamp with time zone DEFAULT now() NOT NULL, "updatedAt" timestamp with time zone DEFAULT now() NOT NULL, "tenantId" uuid, "organizationId" uuid, "projectId" uuid, "deletedAt" timestamp without time zone, "definitionId" uuid NOT NULL, revision integer DEFAULT 1 NOT NULL, configuration jsonb NOT NULL, CONSTRAINT pipeline_binding_values_check CHECK ((revision > 0)) );
CREATE TABLE public.xpert_project_pipeline_decision ( id uuid DEFAULT gen_random_uuid() NOT NULL, "createdById" uuid, "updatedById" uuid, "createdAt" timestamp with time zone DEFAULT now() NOT NULL, "updatedAt" timestamp with time zone DEFAULT now() NOT NULL, "tenantId" uuid, "organizationId" uuid, "projectId" uuid, "deletedAt" timestamp without time zone, "nodeInstanceId" uuid NOT NULL, "roundId" uuid NOT NULL, "operationId" uuid NOT NULL, kind character varying NOT NULL, "policyRef" character varying NOT NULL, "inputDigest" character varying NOT NULL, generation integer NOT NULL, outcome character varying NOT NULL, evidence jsonb NOT NULL, "actorId" uuid NOT NULL, CONSTRAINT pipeline_decision_values_check CHECK (((generation > 0) AND ((kind)::text = ANY ((ARRAY['policy'::character varying, 'human'::character varying])::text[])))) );
CREATE TABLE public.xpert_project_pipeline_definition ( id uuid DEFAULT gen_random_uuid() NOT NULL, "createdById" uuid, "updatedById" uuid, "createdAt" timestamp with time zone DEFAULT now() NOT NULL, "updatedAt" timestamp with time zone DEFAULT now() NOT NULL, "tenantId" uuid, "organizationId" uuid, "projectId" uuid, "deletedAt" timestamp without time zone, "ownerRef" character varying NOT NULL, "templateKey" character varying NOT NULL, version character varying NOT NULL, digest character varying NOT NULL, definition jsonb NOT NULL );
CREATE TABLE public.xpert_project_pipeline_event ( id uuid DEFAULT gen_random_uuid() NOT NULL, "createdById" uuid, "updatedById" uuid, "createdAt" timestamp with time zone DEFAULT now() NOT NULL, "updatedAt" timestamp with time zone DEFAULT now() NOT NULL, "tenantId" uuid, "organizationId" uuid, "projectId" uuid, "deletedAt" timestamp without time zone, "instanceId" uuid NOT NULL, revision integer NOT NULL, type character varying NOT NULL, payload jsonb NOT NULL, CONSTRAINT pipeline_event_values_check CHECK ((revision > 0)) );
CREATE TABLE public.xpert_project_pipeline_instance ( id uuid DEFAULT gen_random_uuid() NOT NULL, "createdById" uuid, "updatedById" uuid, "createdAt" timestamp with time zone DEFAULT now() NOT NULL, "updatedAt" timestamp with time zone DEFAULT now() NOT NULL, "tenantId" uuid, "organizationId" uuid, "projectId" uuid, "deletedAt" timestamp without time zone, "ownerRef" character varying NOT NULL, "sourceKey" character varying NOT NULL, authority character varying NOT NULL, title character varying NOT NULL, "definitionId" uuid NOT NULL, subject jsonb NOT NULL, "currentRunId" uuid, "currentRoundId" uuid, "sourceEpoch" uuid, "sourceSequence" bigint, "snapshotDigest" character varying, revision integer DEFAULT 0 NOT NULL, "nativeModelBudget" jsonb, CONSTRAINT pipeline_instance_values_check CHECK (((revision >= 0) AND ((authority)::text = ANY ((ARRAY['provider'::character varying, 'platform'::character varying])::text[])) AND (("sourceSequence" IS NULL) OR (("sourceSequence" >= 0) AND ("sourceSequence" <= '9007199254740991'::bigint))))) );
CREATE TABLE public.xpert_project_pipeline_model_reservation ( id uuid DEFAULT gen_random_uuid() NOT NULL, "createdById" uuid, "updatedById" uuid, "createdAt" timestamp with time zone DEFAULT now() NOT NULL, "updatedAt" timestamp with time zone DEFAULT now() NOT NULL, "tenantId" uuid, "organizationId" uuid, "projectId" uuid, "deletedAt" timestamp without time zone, "instanceId" uuid NOT NULL, "operationId" uuid NOT NULL, "executionId" uuid NOT NULL, "requestId" uuid NOT NULL, state character varying NOT NULL, "reservedTokens" bigint NOT NULL, "actualTokens" bigint, CONSTRAINT pipeline_model_reservation_values_check CHECK ((((state)::text = ANY ((ARRAY['held'::character varying, 'settled'::character varying])::text[])) AND ("reservedTokens" > 0) AND ((((state)::text = 'held'::text) AND ("actualTokens" IS NULL)) OR (((state)::text = 'settled'::text) AND ("actualTokens" > 0))))) );
CREATE TABLE public.xpert_project_pipeline_native_grant ( id uuid DEFAULT gen_random_uuid() NOT NULL, "createdById" uuid, "updatedById" uuid, "createdAt" timestamp with time zone DEFAULT now() NOT NULL, "updatedAt" timestamp with time zone DEFAULT now() NOT NULL, "tenantId" uuid, "organizationId" uuid, "projectId" uuid, "deletedAt" timestamp without time zone, "instanceId" uuid NOT NULL, "runId" uuid NOT NULL, "roundId" uuid NOT NULL, "nodeInstanceId" uuid NOT NULL, "providerActionId" uuid NOT NULL, "callKey" character varying NOT NULL, "leaseOwner" uuid NOT NULL, "leaseFence" integer NOT NULL, "executionId" uuid NOT NULL, "conversationId" uuid NOT NULL, "xpertId" uuid NOT NULL, "workspaceId" uuid NOT NULL, "publishedVersion" character varying NOT NULL, "inputDigest" character varying NOT NULL, "consumedAt" timestamp with time zone, CONSTRAINT pipeline_native_grant_values_check CHECK (((length(("callKey")::text) > 0) AND ("leaseFence" > 0) AND (length(("publishedVersion")::text) > 0) AND (("inputDigest")::text ~ '^[a-f0-9]{64}$'::text))) );
CREATE TABLE public.xpert_project_pipeline_node ( id uuid DEFAULT gen_random_uuid() NOT NULL, "createdById" uuid, "updatedById" uuid, "createdAt" timestamp with time zone DEFAULT now() NOT NULL, "updatedAt" timestamp with time zone DEFAULT now() NOT NULL, "tenantId" uuid, "organizationId" uuid, "projectId" uuid, "deletedAt" timestamp without time zone, "roundId" uuid NOT NULL, "sourceKey" character varying NOT NULL, "nodeKey" character varying NOT NULL, "expansionKey" character varying NOT NULL, disposition character varying DEFAULT 'active'::character varying NOT NULL, projection jsonb NOT NULL, "taskIds" jsonb DEFAULT '[]'::jsonb NOT NULL, CONSTRAINT pipeline_node_values_check CHECK (((disposition)::text = ANY ((ARRAY['active'::character varying, 'removed'::character varying, 'excluded'::character varying, 'superseded'::character varying])::text[]))) );
CREATE TABLE public.xpert_project_pipeline_operation ( id uuid DEFAULT gen_random_uuid() NOT NULL, "createdById" uuid, "updatedById" uuid, "createdAt" timestamp with time zone DEFAULT now() NOT NULL, "updatedAt" timestamp with time zone DEFAULT now() NOT NULL, "tenantId" uuid, "organizationId" uuid, "projectId" uuid, "deletedAt" timestamp without time zone, "instanceId" uuid NOT NULL, "runId" uuid NOT NULL, "roundId" uuid NOT NULL, "nodeInstanceId" uuid NOT NULL, attempt integer NOT NULL, kind character varying NOT NULL, "handlerRef" character varying NOT NULL, "completionRef" character varying, "snapshotDigest" character varying NOT NULL, context jsonb NOT NULL, "resourceReservation" jsonb, state character varying NOT NULL, receipt jsonb, completion jsonb, "leaseOwner" uuid, "leaseFence" integer DEFAULT 0 NOT NULL, "leaseExpiresAt" timestamp with time zone, "nextCheckAt" timestamp with time zone NOT NULL, "dispatchStartedAt" timestamp with time zone, "terminalObservedAt" timestamp with time zone, "cancelRequestedAt" timestamp with time zone, "cancelDispatchedAt" timestamp with time zone, "assistantIntent" jsonb, "runtimeIntent" jsonb, CONSTRAINT pipeline_operation_values_check CHECK (((attempt > 0) AND (attempt <= 20) AND ("leaseFence" >= 0) AND ((kind)::text = ANY ((ARRAY['operation'::character varying, 'policy'::character varying, 'subscription'::character varying])::text[])) AND ((state)::text = ANY ((ARRAY['queued'::character varying, 'dispatching'::character varying, 'pending'::character varying, 'unknown'::character varying, 'succeeded'::character varying, 'failed'::character varying, 'accepted'::character varying, 'rejected'::character varying, 'cancelled'::character varying, 'superseded'::character varying])::text[])))) );
CREATE TABLE public.xpert_project_pipeline_provider_action ( id uuid DEFAULT gen_random_uuid() NOT NULL, "createdById" uuid, "updatedById" uuid, "createdAt" timestamp with time zone DEFAULT now() NOT NULL, "updatedAt" timestamp with time zone DEFAULT now() NOT NULL, "tenantId" uuid, "organizationId" uuid, "projectId" uuid, "deletedAt" timestamp without time zone, "instanceId" uuid NOT NULL, "runId" uuid NOT NULL, "roundId" uuid NOT NULL, "nodeInstanceId" uuid NOT NULL, "providerRef" character varying NOT NULL, "sourceKey" character varying NOT NULL, digest character varying NOT NULL, input jsonb NOT NULL, node jsonb NOT NULL, state character varying NOT NULL, receipt jsonb, "reasonCode" character varying, "leaseOwner" uuid, "leaseFence" integer DEFAULT 0 NOT NULL, "leaseExpiresAt" timestamp with time zone, "dispatchStartedAt" timestamp with time zone, "nextCheckAt" timestamp with time zone NOT NULL, "projectionPending" boolean DEFAULT false NOT NULL, CONSTRAINT pipeline_provider_action_values_check CHECK ((("leaseFence" >= 0) AND ((state)::text = ANY ((ARRAY['queued'::character varying, 'dispatching'::character varying, 'pending'::character varying, 'unknown'::character varying, 'succeeded'::character varying, 'failed'::character varying, 'superseded'::character varying])::text[])))) );
CREATE TABLE public.xpert_project_pipeline_refresh ( id uuid DEFAULT gen_random_uuid() NOT NULL, "createdById" uuid, "updatedById" uuid, "createdAt" timestamp with time zone DEFAULT now() NOT NULL, "updatedAt" timestamp with time zone DEFAULT now() NOT NULL, "tenantId" uuid, "organizationId" uuid, "projectId" uuid, "deletedAt" timestamp without time zone, "ownerRef" character varying NOT NULL, "sourceKey" character varying NOT NULL, "requestId" uuid NOT NULL, state character varying NOT NULL, "errorCode" character varying, CONSTRAINT pipeline_refresh_values_check CHECK (((state)::text = ANY ((ARRAY['queued'::character varying, 'running'::character varying, 'ready'::character varying, 'not_found'::character varying, 'failed'::character varying])::text[]))) );
CREATE TABLE public.xpert_project_pipeline_round ( id uuid DEFAULT gen_random_uuid() NOT NULL, "createdById" uuid, "updatedById" uuid, "createdAt" timestamp with time zone DEFAULT now() NOT NULL, "updatedAt" timestamp with time zone DEFAULT now() NOT NULL, "tenantId" uuid, "organizationId" uuid, "projectId" uuid, "deletedAt" timestamp without time zone, "runId" uuid NOT NULL, "sourceKey" character varying NOT NULL, sequence integer NOT NULL, generation integer NOT NULL, "inputDigest" character varying NOT NULL, "subjectVersionSet" jsonb NOT NULL, state character varying NOT NULL, edges jsonb DEFAULT '[]'::jsonb NOT NULL, "projectionTasks" jsonb, CONSTRAINT pipeline_round_values_check CHECK (((sequence > 0) AND (generation > 0) AND ((state)::text = ANY ((ARRAY['active'::character varying, 'completed'::character varying, 'awaiting_new_subject'::character varying, 'failed'::character varying, 'cancelled'::character varying, 'superseded'::character varying])::text[])))) );
CREATE TABLE public.xpert_project_pipeline_run ( id uuid DEFAULT gen_random_uuid() NOT NULL, "createdById" uuid, "updatedById" uuid, "createdAt" timestamp with time zone DEFAULT now() NOT NULL, "updatedAt" timestamp with time zone DEFAULT now() NOT NULL, "tenantId" uuid, "organizationId" uuid, "projectId" uuid, "deletedAt" timestamp without time zone, "instanceId" uuid NOT NULL, "sourceKey" character varying NOT NULL, "definitionId" uuid NOT NULL, "bindingSnapshot" jsonb, state character varying NOT NULL, CONSTRAINT pipeline_run_values_check CHECK (((state)::text = ANY ((ARRAY['pending'::character varying, 'active'::character varying, 'waiting'::character varying, 'cancelling'::character varying, 'completed'::character varying, 'failed'::character varying, 'cancelled'::character varying, 'superseded'::character varying])::text[]))) );
