CREATE TABLE public.xpert_project_task ( id uuid DEFAULT gen_random_uuid() NOT NULL, "createdById" uuid, "updatedById" uuid, "createdAt" timestamp with time zone DEFAULT now() NOT NULL, "updatedAt" timestamp with time zone DEFAULT now() NOT NULL, "tenantId" uuid, "organizationId" uuid, "projectId" uuid, "deletedAt" timestamp without time zone, "controlKind" character varying DEFAULT 'ordinary'::character varying NOT NULL, "pipelineInstanceId" uuid, "pipelineDisposition" character varying, decisions jsonb DEFAULT '[]'::jsonb NOT NULL, progress double precision, "providerKey" character varying, "sourceKey" character varying, "sourceRevision" character varying, revision integer DEFAULT 1 NOT NULL, kind character varying DEFAULT 'task'::character varying NOT NULL, "parentTaskId" uuid, "predecessorIds" json DEFAULT '[]'::json NOT NULL, "plannedStartAt" timestamp with time zone, "plannedEndAt" timestamp with time zone, "estimatedDurationMs" double precision, diagnostic text, "threadId" character varying, name character varying, title character varying, description text, requirements jsonb DEFAULT '[]'::jsonb NOT NULL, type character varying, status public.xpert_project_task_status_enum, priority public.xpert_project_task_priority_enum, "assigneeId" character varying, "assigneeXpertId" character varying, "dueDate" timestamp with time zone, "planId" character varying, "milestoneId" character varying, "column" character varying, "order" integer DEFAULT 0, "startTime" timestamp without time zone, "endTime" timestamp without time zone, CONSTRAINT pipeline_task_control_check CHECK (((("controlKind")::text = ANY ((ARRAY['ordinary'::character varying, 'provider'::character varying, 'pipeline'::character varying])::text[])) AND ((("controlKind")::text <> 'pipeline'::text) OR ("pipelineInstanceId" IS NOT NULL)) AND (("pipelineInstanceId" IS NULL) OR ("projectId" IS NOT NULL)) AND (("pipelineDisposition" IS NULL) OR (("pipelineInstanceId" IS NOT NULL) AND (("pipelineDisposition")::text = ANY ((ARRAY['active'::character varying, 'removed'::character varying, 'excluded'::character varying, 'superseded'::character varying])::text[])))))) );
